fn completed_cloud_modules_have_valid_vertex_and_fragment_interfaces() {
    use wgpu::naga;
    for source in [include_str!("cloud_points.wgsl"), include_str!("cloud_resolve.wgsl")] {
        let module = naga::front::wgsl::parse_str(source)
