pub fn view(&self, queue: &wgpu::Queue, transform: &[f32; 16], size: [u32; 2], density: f32) {
    for lane in [&self.strokes, &self.paths, &self.markers] { lane.view(queue, transform, size, density); }
}

pub fn view(&self, queue: &wgpu::Queue, transform: &[f32; 16], size: [u32; 2], density: f32) {
