        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("actual distinct samples"),
            source: wgpu::ShaderSource::Wgsl(r#"
@vertex fn vertex(@builtin(vertex_index) i:u32)->@builtin(position) vec4f {
